<?php
class Reporte_equipajes_model extends CI_Model{
 public function usuario_tiene_rol($u,$r){return !empty($this->db->query("SELECT 1 x FROM usuario u INNER JOIN rol_usuario ru ON ru.tipousuario_id=u.tipousuario_id WHERE u.usuario_id=? AND ru.rol_id=? AND ru.rolusuario_asignado=1 LIMIT 1",array((int)$u,(int)$r))->row_array());}
 private function where($f,&$p){$w="DATE(e.equipaje_fechahorarecepcion) BETWEEN ? AND ?";$p=array($f['desde'],$f['hasta']);if($f['viaje_id']>0){$w.=" AND e.viaje_id=?";$p[]=$f['viaje_id'];}if($f['estado']!==''){$w.=" AND e.equipaje_estado=?";$p[]=$f['estado'];}return $w;}
 public function viajes($f){return $this->db->query("SELECT v.viaje_id,v.viaje_fechasalida,v.viaje_horasalida,COALESCE(r.ruta_nombre,CONCAT_WS(' - ',r.inicio_ruta,r.fin_ruta)) ruta FROM viaje v LEFT JOIN ruta r ON r.ruta_id=v.ruta_id WHERE v.viaje_fechasalida BETWEEN ? AND ? ORDER BY v.viaje_fechasalida DESC,v.viaje_horasalida DESC",array($f['desde'],$f['hasta']))->result_array();}
 public function reporte($f){$p=array();$w=$this->where($f,$p);$sql="SELECT e.equipaje_id,e.equipaje_numeroetiqueta etiqueta,e.equipaje_estado estado,e.equipaje_cantidad_piezas cantidad,e.equipaje_peso peso,e.equipaje_exceso_kg exceso,e.equipaje_importe importe,e.equipaje_fechahorarecepcion recibido,e.equipaje_fechahoraentrega entregado,p.pasaje_nombre pasajero,p.pasaje_documento documento,COALESCE(a.asiento_numero,'') asiento,v.viaje_fechasalida fecha_viaje,CONCAT('#',v.viaje_id,' - ',COALESCE(r.ruta_nombre,CONCAT_WS(' - ',r.inicio_ruta,r.fin_ruta)),' - ',TIME_FORMAT(v.viaje_horasalida,'%H:%i')) viaje FROM pasaje_equipaje e INNER JOIN pasaje p ON p.pasaje_id=e.pasaje_id LEFT JOIN asientos a ON a.asiento_id=p.asiento_id LEFT JOIN viaje v ON v.viaje_id=e.viaje_id LEFT JOIN ruta r ON r.ruta_id=v.ruta_id WHERE $w ORDER BY e.equipaje_fechahorarecepcion DESC,e.equipaje_id DESC";return $this->db->query($sql,$p)->result_array();}
 public function totales($f){$p=array();$w=$this->where($f,$p);return $this->db->query("SELECT COUNT(*) registros,COALESCE(SUM(e.equipaje_cantidad_piezas),0) piezas,COALESCE(SUM(e.equipaje_peso),0) peso,COALESCE(SUM(e.equipaje_exceso_kg),0) exceso,COALESCE(SUM(e.equipaje_importe),0) importe,SUM(CASE WHEN e.equipaje_fechahoraentrega IS NOT NULL THEN 1 ELSE 0 END) entregados,SUM(CASE WHEN e.equipaje_fechahoraentrega IS NULL THEN 1 ELSE 0 END) pendientes FROM pasaje_equipaje e WHERE $w",$p)->row_array();}
}
